const inp = $input.first().json;
const payload = inp.body ?? inp;
const data = payload.data ?? {};
const analysis = data.analysis ?? {};
const dcr = analysis.data_collection_results ?? {};
const meta = data.metadata ?? {};
const phone = meta.phone_call ?? {};
const val = (k) => (dcr[k] && dcr[k].value != null && String(dcr[k].value).trim() !== '' ? String(dcr[k].value).trim() : null);

let transcriptText = null;
if (Array.isArray(data.transcript)) {
  transcriptText = data.transcript
    .map(t => `${t.role === 'agent' ? 'Assistentin' : 'Anrufer'}: ${t.message ?? ''}`)
    .filter(s => s.replace(/^[^:]*:\s*/, '').trim().length > 0)
    .join('\n');
}

const bestTime = val('beste_uhrzeit');
let anliegen = val('anliegen');
if (bestTime) anliegen = (anliegen ? anliegen + ' ' : '') + `(Beste Rückrufzeit: ${bestTime})`;

const duration = Number(meta.call_duration_secs ?? 0) || null;
const isSpam = !!(dcr.ist_spam && (dcr.ist_spam.value === true || dcr.ist_spam.value === 'true'));
const convId = data.conversation_id ?? null;

const row = {
  quelle: 'telefon',
  seite: 'gbp',
  name: val('name'),
  firma: val('firma'),
  telefon: val('telefon') || phone.external_number || null,
  caller_id: phone.external_number || null,
  email: val('email'),
  anliegen,
  branche: val('branche'),
  stadt: val('stadt'),
  sprache: val('sprache') || 'de',
  zusammenfassung: analysis.transcript_summary ?? null,
  transcript: transcriptText,
  recording_url: convId ? `https://elevenlabs.io/app/conversational-ai/history/${convId}` : null,
  dauer_sekunden: duration,
  conversation_id: convId,
  status: 'neu'
};

const hasContact = !!(row.name || row.telefon);
const keep = !isSpam && (duration === null || duration >= 10) && hasContact;

const tg = [
  '📞 Neuer Anruf — 741 Studio',
  row.name ? `👤 ${row.name}` : null,
  row.firma ? `🏢 ${row.firma}` : null,
  row.telefon ? `☎️ ${row.telefon}` : null,
  row.stadt ? `📍 ${row.stadt}` : null,
  row.anliegen ? `📝 ${row.anliegen}` : null,
  row.zusammenfassung ? `\n${row.zusammenfassung}` : null,
  row.recording_url ? `\n🎧 ${row.recording_url}` : null
].filter(Boolean).join('\n');

return [{ json: { keep, isSpam, duration, row, telegram_text: tg } }];
